   1	/**
   2	 * Document Loader — Read files from disk and prepare them for vector indexing.
   3	 *
   4	 * Supports: Markdown, JSON, TypeScript/JavaScript, and plain text files.
   5	 * Automatically chunks large documents and preserves metadata (file path, type).
   6	 */
   7	
   8	import { readFileSync, readdirSync, statSync } from "node:fs";
   9	import { extname, join, relative } from "node:path";
  10	import type { VectorDocumentInput } from "./types.js";
  11	import { RAGError } from "./types.js";
  12	
  13	// ── Types ────────────────────────────────────────────────────────────────────
  14	
  15	export type SupportedFileType = "markdown" | "json" | "typescript" | "text";
  16	
  17	export interface DocumentLoaderOptions {
  18	  /** Root directory to scan */
  19	  rootDir: string;
  20	  /** File extensions to include (default: all supported) */
  21	  extensions?: string[];
  22	  /** Patterns to exclude (glob-like, matched against relative path) */
  23	  exclude?: string[];
  24	  /** Maximum file size in bytes (default: 1MB) */
  25	  maxFileSize?: number;
  26	  /** Chunk size in characters (default: 1500) */
  27	  chunkSize?: number;
  28	  /** Chunk overlap in characters (default: 200) */
  29	  chunkOverlap?: number;
  30	  /** Custom prefix for document IDs (default: relative file path) */
  31	  idPrefix?: string;
  32	}
  33	
  34	export interface LoadedDocument {
  35	  /** Unique document ID */
  36	  id: string;
  37	  /** Text content (or chunk) */
  38	  content: string;
  39	  /** Metadata */
  40	  metadata: Record<string, unknown>;
  41	}
  42	
  43	export interface LoadResult {
  44	  /** All loaded documents/chunks */
  45	  documents: VectorDocumentInput[];
  46	  /** Number of files scanned */
  47	  filesScanned: number;
  48	  /** Number of files loaded (passed filters) */
  49	  filesLoaded: number;
  50	  /** Number of chunks produced */
  51	  chunksProduced: number;
  52	}
  53	
  54	// ── Extension Mapping ────────────────────────────────────────────────────────
  55	
  56	const EXTENSION_MAP: Record<string, SupportedFileType> = {
  57	  ".md": "markdown",
  58	  ".mdx": "markdown",
  59	  ".json": "json",
  60	  ".jsonl": "json",
  61	  ".ts": "typescript",
  62	  ".tsx": "typescript",
  63	  ".js": "text",
  64	  ".jsx": "text",
  65	  ".mjs": "text",
  66	  ".cjs": "text",
  67	  ".txt": "text",
  68	  ".log": "text",
  69	  ".yaml": "text",
  70	  ".yml": "text",
  71	  ".toml": "text",
  72	  ".ini": "text",
  73	  ".cfg": "text",
  74	  ".env": "text",
  75	  ".sh": "text",
  76	  ".bash": "text",
  77	  ".zsh": "text",
  78	  ".py": "text",
  79	  ".go": "text",
  80	  ".rs": "text",
  81	  ".java": "text",
  82	  ".c": "text",
  83	  ".cpp": "text",
  84	  ".h": "text",
  85	  ".css": "text",
  86	  ".html": "text",
  87	  ".xml": "text",
  88	  ".sql": "text",
  89	};
  90	
  91	const DEFAULT_EXTENSIONS = Object.keys(EXTENSION_MAP);
  92	
  93	// ── Document Loader ──────────────────────────────────────────────────────────
  94	
  95	export class DocumentLoader {
  96	  private rootDir: string;
  97	  private extensions: Set<string>;
  98	  private excludePatterns: string[];
  99	  private maxFileSize: number;
 100	  private chunkSize: number;
 101	  private chunkOverlap: number;
 102	  private idPrefix: string;
 103	
 104	  constructor(options: DocumentLoaderOptions) {
 105	    if (!options.rootDir) throw new RAGError("LOADER_ERROR", "rootDir is required");
 106	    this.rootDir = options.rootDir;
 107	    this.extensions = new Set(options.extensions ?? DEFAULT_EXTENSIONS);
 108	    this.excludePatterns = options.exclude ?? [
 109	      "node_modules",
 110	      ".git",
 111	      "dist",
 112	      "build",
 113	      ".next",
 114	      "coverage",
 115	    ];
 116	    this.maxFileSize = options.maxFileSize ?? 1_000_000; // 1MB
 117	    this.chunkSize = options.chunkSize ?? 1500;
 118	    this.chunkOverlap = options.chunkOverlap ?? 200;
 119	    this.idPrefix = options.idPrefix ?? "";
 120	  }
 121	
 122	  /**
 123	   * Load all matching files from the root directory.
 124	   */
 125	  load(): LoadResult {
 126	    const files = this.scanDir(this.rootDir);
 127	    const documents: VectorDocumentInput[] = [];
 128	    let filesLoaded = 0;
 129	
 130	    for (const filePath of files) {
 131	      try {
 132	        const content = this.readFile(filePath);
 133	        if (!content) continue;
 134	
 135	        filesLoaded++;
 136	        const relPath = relative(this.rootDir, filePath);
 137	        const fileType = this.getFileType(filePath);
 138	        const chunks = this.chunkText(content);
 139	
 140	        for (let i = 0; i < chunks.length; i++) {
 141	          const id = this.idPrefix
 142	            ? `${this.idPrefix}:${relPath}:${i}`
 143	            : `${relPath}:${i}`;
 144	          documents.push({
 145	            id,
 146	            content: chunks[i],
 147	            metadata: {
 148	              source: relPath,
 149	              fileType,
 150	              chunkIndex: i,
 151	              totalChunks: chunks.length,
 152	            },
 153	          });
 154	        }
 155	      } catch {
 156	        // Skip files that can't be read
 157	      }
 158	    }
 159	
 160	    return {
 161	      documents,
 162	      filesScanned: files.length,
 163	      filesLoaded,
 164	      chunksProduced: documents.length,
 165	    };
 166	  }
 167	
 168	  /**
 169	   * Load a single file and return its document inputs.
 170	   */
 171	  loadFile(filePath: string): VectorDocumentInput[] {
 172	    const content = this.readFile(filePath);
 173	    if (!content) return [];
 174	
 175	    const relPath = relative(this.rootDir, filePath);
 176	    const fileType = this.getFileType(filePath);
 177	    const chunks = this.chunkText(content);
 178	
 179	    return chunks.map((chunk, i) => ({
 180	      id: this.idPrefix ? `${this.idPrefix}:${relPath}:${i}` : `${relPath}:${i}`,
 181	      content: chunk,
 182	      metadata: {
 183	        source: relPath,
 184	        fileType,
 185	        chunkIndex: i,
 186	        totalChunks: chunks.length,
 187	      },
 188	    }));
 189	  }
 190	
 191	  // ── Internal ─────────────────────────────────────────────────────────────
 192	
 193	  private scanDir(dir: string): string[] {
 194	    const results: string[] = [];
 195	    try {
 196	      const entries = readdirSync(dir, { withFileTypes: true });
 197	      for (const entry of entries) {
 198	        const fullPath = join(dir, entry.name);
 199	        const relPath = relative(this.rootDir, fullPath);
 200	
 201	        if (this.shouldExclude(relPath)) continue;
 202	
 203	        if (entry.isDirectory()) {
 204	          results.push(...this.scanDir(fullPath));
 205	        } else if (entry.isFile()) {
 206	          const ext = extname(entry.name).toLowerCase();
 207	          if (this.extensions.has(ext)) {
 208	            results.push(fullPath);
 209	          }
 210	        }
 211	      }
 212	    } catch {
 213	      // Skip directories that can't be read
 214	    }
 215	    return results;
 216	  }
 217	
 218	  private shouldExclude(relPath: string): boolean {
 219	    return this.excludePatterns.some((pattern) => {
 220	      if (pattern.includes("*") || pattern.includes("?")) {
 221	        // Simple glob: match against each path segment
 222	        const segments = relPath.split("/");
 223	        return segments.some((s) => this.simpleGlob(s, pattern));
 224	      }
 225	      return relPath.includes(pattern);
 226	    });
 227	  }
 228	
 229	  private simpleGlob(text: string, pattern: string): boolean {
 230	    const regex = new RegExp(
 231	      "^" + pattern.replace(/\./g, "\\.").replace(/\*/g, ".*").replace(/\?/g, ".") + "$",
 232	    );
 233	    return regex.test(text);
 234	  }
 235	
 236	  private readFile(filePath: string): string | null {
 237	    try {
 238	      const stat = statSync(filePath);
 239	      if (stat.size > this.maxFileSize) return null;
 240	      if (stat.size === 0) return null;
 241	      return readFileSync(filePath, "utf-8");
 242	    } catch {
 243	      return null;
 244	    }
 245	  }
 246	
 247	  private getFileType(filePath: string): SupportedFileType {
 248	    const ext = extname(filePath).toLowerCase();
 249	    return EXTENSION_MAP[ext] ?? "text";
 250	  }
 251	
 252	  /**
 253	   * Split text into overlapping chunks.
 254	   * Tries to split at paragraph/sentence boundaries when possible.
 255	   */
 256	  chunkText(text: string): string[] {
 257	    if (text.length <= this.chunkSize) return [text];
 258	
 259	    const chunks: string[] = [];
 260	    let start = 0;
 261	
 262	    while (start < text.length) {
 263	      let end = Math.min(start + this.chunkSize, text.length);
 264	
 265	      // Try to find a natural break point (paragraph or sentence)
 266	      if (end < text.length) {
 267	        const slice = text.slice(start, end);
 268	        const paragraphBreak = slice.lastIndexOf("\n\n");
 269	        const sentenceBreak = slice.lastIndexOf(". ");
 270	
 271	        if (paragraphBreak > this.chunkSize * 0.5) {
 272	          end = start + paragraphBreak + 2;
 273	        } else if (sentenceBreak > this.chunkSize * 0.5) {
 274	          end = start + sentenceBreak + 2;
 275	        }
 276	      }
 277	
 278	      chunks.push(text.slice(start, end).trim());
 279	
 280	      // Move start forward, accounting for overlap
 281	      const nextStart = end - this.chunkOverlap;
 282	      if (nextStart <= start) {
 283	        // Prevent infinite loop: force advance
 284	        start = end;
 285	      } else {
 286	        start = nextStart;
 287	      }
 288	    }
 289	
 290	    return chunks.filter((c) => c.length > 0);
 291	  }
 292	}
 293	
 294	// ── Factory ──────────────────────────────────────────────────────────────────
 295	
 296	export function createDocumentLoader(options: DocumentLoaderOptions): DocumentLoader {
 297	  return new DocumentLoader(options);
 298	}
